2.4 Création de buffer pour les AP avant et après 2008
On travaille toujours avec les portions terrestres des AP.
Pour analyser l’impact des AP selon leur période de création, on spécifie, pour chaque vague d’enquête, les AP antérieures à 2008 (en vigueur à la date de référence de la vague) et l’univers de traitement (AP créées à partir de 2008, limites effectives définies plus haut : limite de création pour les AP futures, limite en vigueur pour les AP actives). On applique ensuite un buffer zone de 10 km autour de chaque groupe d’AP. Chaque groupe a été reprojeté dans le système de projection officiel de Madagascar, qui est le Laborde (EPSG : 29702) pour les calculs de distances. Nous créons ensuite une carte pour visualiser les AP et leurs zones d’influence, en prenant la vague 2008 comme exemple. Exception : pour l’enquête 1997, utilisée comme test de placebo, on applique l’état du réseau d’AP de 2008 (et donc les buffers de 2008).


Code
# Buffer de 10 km
buffer_dist &lt;- 10000 

# Fonction de création du buffer de 10 km (reprojection Laborde pour les
# calculs de distance, union des AP, puis retour en WGS 84). Définie une
# seule fois ici et réutilisée par la classification des clusters.
buffer_10km &lt;- function(pa, buffer_dist = 10000) {
  if (nrow(pa) == 0) return(st_as_sf(st_sfc(st_polygon(), crs = standard_crs)))
  pa |&gt;
    st_transform(mdg_crs) |&gt;
    st_buffer(dist = buffer_dist) |&gt;
    st_make_valid() |&gt;
    st_union() |&gt;
    st_as_sf() |&gt;
    st_make_valid() |&gt;
    st_transform(standard_crs)
}

# Exemple 2008 : couches et buffers utilisés pour les cartes ci-dessous.
# À la date de référence de l'enquête 2008 (1er juin), aucune AP de l'univers
# de traitement n'est encore en vigueur (créations oct.-déc. 2008) : la couche
# "from_2008" montre leurs limites de création, qui délimitent la géographie
# de traitement futur.
pad_empty &lt;- function(x) {
  if (nrow(x) == 0) {
    st_as_sf(st_sfc(st_polygon(), crs = st_crs(x)))
  } else x
}
lay_2008 &lt;- pa_layers(2008)
wdpa_before_2008 &lt;- lay_2008$pre |&gt; pad_empty()
wdpa_from_2008   &lt;- lay_2008$univ_future |&gt; pad_empty()

buffer_10km_before_2008 &lt;- buffer_10km(lay_2008$pre)
buffer_10km_from_2008   &lt;- buffer_10km(lay_2008$univ)

# Visualisation des cartes 
tmap_mode("plot")

tm_shape(contour_mada) + 
  tm_borders() +
tm_shape(wdpa_before_2008) +
tm_polygons(fill = "blue", 
            col =  "black", 
            fill_alpha = 0.5) +
tm_shape(buffer_10km_from_2008) +
tm_borders(col = "darkgreen", lwd = 1, fill.legend = tm_legend_hide()) +
tm_shape(buffer_10km_before_2008) +
tm_borders(col = "blue", lwd = 1, fill.legend = tm_legend_hide()) +
tm_shape(wdpa_from_2008) +
tm_polygons(fill = "darkgreen", 
            col = "black", 
            fill_alpha = 0.5) +
tm_add_legend(type = "polygons", fill = c("blue", "darkgreen"), labels = c("Before June 2008", "After June 2008")) +
  tm_title("Protected areas by period of creation", fontface = "bold", size = 1) +
  tm_credits("Source: WDPA, 2025", position =  c("BOTTOM", "RIGHT")) +
  tm_scalebar(position = c("TOP", "LEFT"))





Figure 5: Protected areas by period of creation




On agrège les données pour chaque groupe, en calculant le nombre total d’aires protégées et leur superficie totale, que l’on présente sous forme de tableau.


Code
library(gt)

pivot_year &lt;- 2008

# Année de création : premier STATUS_YR connu de chaque AP (le STATUS_YR est
# réinitialisé à chaque changement de statut, on retient l'état initial).
# Superficie : dernier état de limite connu (pa_states_fixed, hors AP
# "Proposed"), base dynamic_wdpa.
pa_crea &lt;- pa_states_analysis |&gt;
  group_by(WDPAID) |&gt;
  slice_min(valid_from, n = 1, with_ties = FALSE) |&gt;
  ungroup() |&gt;
  st_drop_geometry() |&gt;
  select(WDPAID, STATUS_YR)

pa_area &lt;- pa_states_fixed |&gt;
  mutate(area_km2 = as.numeric(st_area(geometry)) / 1e6) |&gt;
  st_drop_geometry() |&gt;
  select(WDPAID, area_km2)

summary_table &lt;- pa_crea |&gt;
  left_join(pa_area, by = "WDPAID") |&gt;
  mutate(Creation_Period = if_else(
           STATUS_YR &lt; pivot_year,
           paste("Before June", pivot_year),
           paste("After June", pivot_year)
         )) |&gt;
  group_by(Creation_Period) |&gt;
  summarise(
    Count    = n(),
    Area_km2 = sum(area_km2, na.rm = TRUE),
    .groups  = "drop"
  )

gt_table &lt;- summary_table |&gt;
  gt() |&gt;
  tab_header(
    title    = md("**Protected Areas by Period of Creation**"),
    subtitle = md(paste0("*Madagascar — Reference year: ", pivot_year,
                         " — Terrestrial areas only*"))
  ) |&gt;
  cols_label(
    Creation_Period = md("**Creation Period**"),
    Count           = md("**PA Number**"),
    Area_km2        = md("**Area (km²)**")
  ) |&gt;
  fmt_number(columns = Count,    decimals = 0, use_seps = TRUE) |&gt;
  fmt_number(columns = Area_km2, decimals = 2, use_seps = TRUE) |&gt;
  cols_align(align = "left",  columns = Creation_Period) |&gt;
  cols_align(align = "right", columns = c(Count, Area_km2)) |&gt;
  cols_width(
    Creation_Period ~ px(180),
    Count           ~ px(120),
    Area_km2        ~ px(150)
  ) |&gt;
  tab_style(
    style     = cell_fill(color = "#e8f5e9"),
    locations = cells_body(rows = seq(2, nrow(summary_table), 2))
  ) |&gt;
  tab_style(
    style     = list(
      cell_fill(color = "darkgreen"),
      cell_text(color = "white", weight = "bold", size = px(13))
    ),
    locations = cells_column_labels()
  ) |&gt;
  tab_style(
    style     = cell_text(size = px(18), weight = "bold", color = "darkgreen"),
    locations = cells_title(groups = "title")
  ) |&gt;
  tab_style(
    style     = cell_text(size = px(13), color = "grey40", style = "italic"),
    locations = cells_title(groups = "subtitle")
  ) |&gt;
  grand_summary_rows(
    columns = c(Count, Area_km2),
    fns     = list(Total = ~ sum(.)),
    fmt     = ~ fmt_number(., decimals = 0, use_seps = TRUE)
  ) |&gt;
  tab_style(
    style     = list(
      cell_fill(color = "darkgreen"),
      cell_text(color = "white", weight = "bold")
    ),
    locations = cells_grand_summary()
  ) |&gt;
  tab_footnote(
    footnote  = md("PA = Protected Area as defined by IUCN categories I–VI. Creation year: first STATUS_YR known per PA (dynamic WDPA base); area: latest known boundary."),
    locations = cells_column_labels(columns = Count)
  ) |&gt;
  tab_source_note(md("**Source:** Dynamic conservation boundaries (WDPA-derived), 2025.")) |&gt;
  tab_source_note(md("**Note:** Analysis restricted to terrestrial protected areas in Madagascar; AP « Proposed » excluded.")) |&gt;
  tab_options(
    table.font.names                    = "Times New Roman",
    table.font.size                     = px(13),
    table.width                         = pct(85),
    heading.align                       = "left",
    heading.border.bottom.color         = "darkgreen",
    heading.border.bottom.width         = px(2),
    column_labels.border.top.color      = "darkgreen",
    column_labels.border.top.width      = px(2),
    column_labels.border.bottom.color   = "darkgreen",
    column_labels.border.bottom.width   = px(2),
    column_labels.padding               = px(8),
    table_body.hlines.color             = "#cccccc",
    table_body.hlines.width             = px(0.5),
    table_body.border.bottom.color      = "darkgreen",
    table_body.border.bottom.width      = px(2),
    data_row.padding                    = px(8),
    source_notes.font.size              = px(10),
    source_notes.border.lr.style        = "none",
    source_notes.padding                = px(6),
    footnotes.font.size                 = px(10),
    footnotes.marks                     = "letters"
  )

write_rds(gt_table, "paper/tables/tbl-period-crea.rds")
gtsave(gt_table, "paper/tables/tbl-period-crea.png", expand = 10, zoom = 3)
gt_table




